bool prepare(std::uint64_t id) noexcept {
    if (phase_ != RoundPhase::waiting && phase_ != RoundPhase::ended) {
      return false;
    }
    if (id == 0 || id <= round_) {
      return false;
    }
    round_ = id;
    phase_ = RoundPhase::countdown;
    return true;
  }

bool start() noexcept {
    if (phase_ != RoundPhase::countdown) {
      return false;
    }
    phase_ = RoundPhase::playing;
    return true;
  }

RoundScope classify(std::uint64_t id) const noexcept {
    if (id < round_) {
      return RoundScope::old_round;
    }
    if (id > round_) {
      return RoundScope::future_round;
    }
    if (id != 0 &&
        (phase_ == RoundPhase::countdown || phase_ == RoundPhase::playing)) {
      return RoundScope::current;
    }
    return RoundScope::inactive;
  }

inline bool encode_round_input(const RoundBatch& batch, Frame& out) noexcept {
  if (batch.round == 0 || !valid_input_batch(batch.inputs)) {
    return false;
  }

  // Fill a local candidate; publish only on whole-message success.
  Frame candidate{};
  candidate.type = kRoundInputType;

  ByteWriter writer(candidate.payload.data(), candidate.payload.size());
  if (!writer.u64(batch.round)) {
    return false;
  }
  if (!writer.u32(batch.inputs.first_tick)) {
    return false;
  }
  if (!writer.u16(static_cast<std::uint16_t>(batch.inputs.count))) {
    return false;
  }
  for (std::size_t i = 0; i < batch.inputs.count; ++i) {
    if (!writer.u8(batch.inputs.masks[i])) {
      return false;
    }
  }

  candidate.size = writer.position();
  out = candidate;
  return true;
}

inline bool decode_round_input(const Frame& frame, RoundBatch& out) noexcept {
  if (frame.type != kRoundInputType) {
    return false;
  }
  // Reject an impossible declared size before building a reader.
  if (frame.size > frame.payload.size() || frame.size < kRoundHeaderBytes) {
    return false;
  }

  ByteReader reader(frame.payload.data(), frame.size);

  std::uint64_t round = 0;
  if (!reader.u64(round) || round == 0) {
    return false;
  }

  std::uint32_t first_tick = 0;
  if (!reader.u32(first_tick)) {
    return false;
  }

  std::uint16_t count16 = 0;
  if (!reader.u16(count16)) {
    return false;
  }

  // Narrowing is not range checking: validate before using as a count.
  if (count16 < 1 || count16 > kMaxBatchInputs) {
    return false;
  }

  const std::size_t count = static_cast<std::size_t>(count16);

  // Exact size policy: exactly count mask bytes must remain.
  if (reader.remaining() != count) {
    return false;
  }

  // Build and validate a local candidate before publishing.
  RoundBatch candidate{};
  candidate.round = round;
  candidate.inputs.first_tick = first_tick;
  candidate.inputs.count = count;
  for (std::size_t i = 0; i < count; ++i) {
    if (!reader.u8(candidate.inputs.masks[i])) {
      return false;
    }
  }

  if (!reader.at_end() || !valid_input_batch(candidate.inputs)) {
    return false;
  }

  out = candidate;
  return true;
}

bool prepare(std::uint64_t id, const study_combat::Duel& duel, Side local,
                 unsigned delay, std::uint32_t first = 0) noexcept {
        RoundGate candidate = gate_;
        if (!candidate.prepare(id)) return false;
        auto game = DelayedLockstep::create(duel, local, delay, first);
        if (!game || duel.left().finished() || duel.right().finished()) return false;
        game_ = *game; // Replace the old tick history only after both checks.
        gate_ = candidate;
        return true;
    }

RoundInputResult capture(unsigned mask, Frame& outgoing) noexcept {
        if (!gate_.can_capture()) return {};
        auto candidate = *game_;
        const auto tick = candidate.next_capture_tick();
        const Put result = candidate.capture(mask);
        if (result != Put::stored) return {RoundScope::current, result};
        RoundBatch batch;
        batch.round = gate_.round();
        batch.inputs.first_tick = static_cast<std::uint32_t>(tick);
        batch.inputs.count = 1;
        batch.inputs.masks[0] = static_cast<std::uint8_t>(mask);
        Frame encoded;
        if (!encode_round_input(batch, encoded)) return {RoundScope::current, Put::invalid};
        *game_ = candidate;
        outgoing = encoded;
        return {RoundScope::current, Put::stored};
    }

RoundInputResult receive(const Frame& frame) noexcept {
        RoundBatch batch;
        if (!decode_round_input(frame, batch)) return {RoundScope::invalid_frame, Put::invalid};
        const auto scope = gate_.classify(batch.round);
        if (scope != RoundScope::current) return {scope, Put::invalid};
        return {scope, game_->receive_batch(batch.inputs.first_tick,
                                           batch.inputs.masks.data(), batch.inputs.count)};
    }

Advance advance() noexcept {
        if (gate_.phase() == RoundPhase::ended) return Advance::finished;
        if (gate_.phase() != RoundPhase::playing) return Advance::waiting;
        const auto result = game_->advance();
        if (result == Advance::finished || result == Advance::exhausted ||
            game_->state().left().finished() || game_->state().right().finished())
            (void)gate_.finish();
        return result;
    }
